def group_existing_questions(apps, schema_editor):
    Conversation = apps.get_model('Agent', 'AiAgentConversation')
    Question = apps.get_model('Agent', 'AiAgentQuestion')
    database = schema_editor.connection.alias

    user_ids = list(
        Question.objects.using(database)
        .filter(conversation__isnull=True)
        .values_list('user_id', flat=True)
        .distinct()
    )
    for user_id in user_ids:
        questions = Question.objects.using(database).filter(
            user_id=user_id,
            conversation__isnull=True,
        )
        first_question = questions.order_by('created_at', 'pk').first()
        if first_question is None:
            continue

        conversation = Conversation.objects.using(database).create(
            user_id=user_id,
            title=first_question.question_text[:120],
        )
        questions.update(conversation_id=conversation.pk)


